// `#Region` pairs become `#pragma region` pairs, around the same statements.

/// @sort 32
uniform float A = 1.0;
/// @sort 32
uniform float B = 2.0;

/// @name DreamShaderTests/Migrate/M_MgRegions
export void M_MgRegions(inout material Base)
{
    float Value = 0;
    #pragma region Maths
    float Sum = A + B;
    // inside the region
    float Scaled = Sum * 0.5;
    #pragma endregion
    Value = Scaled;
    Base.Opacity = Value;
}
